import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"快速上手","description":"5 分钟内运行 StreamMUSE 第一个示例","frontmatter":{"title":"快速上手","description":"5 分钟内运行 StreamMUSE 第一个示例"},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md","lastUpdated":1775717144000}'),n={name:"getting-started/quickstart.md"};function d(o,t,l,r,p,c){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>本文将在 5 分钟内带你启动系统、输入旋律并观察到 AI 生成的伴奏。</p><blockquote><p><strong>前提</strong>：已完成<a href="./installation.html">安装指南</a>中的所有步骤。</p></blockquote><hr><h2 id="第一步-启动-fake-推理服务器" tabindex="-1">第一步：启动 Fake 推理服务器 <a class="header-anchor" href="#第一步-启动-fake-推理服务器" aria-label="Permalink to &quot;第一步：启动 Fake 推理服务器&quot;">​</a></h2><p>在第一个终端中运行 fake 服务器（不需要真实模型或 GPU）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/fake_inference_server.py</span></span></code></pre></div><p>Fake 服务器会监听 <code>http://localhost:8000</code>，并将收到的旋律事件回显为伴奏（echo），用于开发和测试。看到以下输出即表示服务器已就绪：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INFO:     Started server process [xxxxx]</span></span>
<span class="line"><span>INFO:     Uvicorn running on http://0.0.0.0:8000</span></span></code></pre></div><hr><h2 id="第二步-启动-cli-客户端" tabindex="-1">第二步：启动 CLI 客户端 <a class="header-anchor" href="#第二步-启动-cli-客户端" aria-label="Permalink to &quot;第二步：启动 CLI 客户端&quot;">​</a></h2><p>在<strong>另一个终端</strong>中，以键盘输入模式、控制台输出启动客户端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keyboard</span></span></code></pre></div><p>看到状态行 <code>[status] state=running message=</code> 即表示系统已开始运行。</p><hr><h2 id="第三步-演奏音符" tabindex="-1">第三步：演奏音符 <a class="header-anchor" href="#第三步-演奏音符" aria-label="Permalink to &quot;第三步：演奏音符&quot;">​</a></h2><p>用以下键盘按键输入音符：</p><table tabindex="0"><thead><tr><th>按键</th><th>MIDI 音高</th><th>音名</th></tr></thead><tbody><tr><td><code>z</code></td><td>60</td><td>C4（中央 C）</td></tr><tr><td><code>x</code></td><td>62</td><td>D4</td></tr><tr><td><code>c</code></td><td>64</td><td>E4</td></tr><tr><td><code>v</code></td><td>65</td><td>F4</td></tr><tr><td><code>b</code></td><td>67</td><td>G4</td></tr><tr><td><code>n</code></td><td>69</td><td>A4</td></tr><tr><td><code>m</code></td><td>71</td><td>B4</td></tr></tbody></table><ul><li><strong>按住</strong>某个键 = 音符持续（NOTE_ON）</li><li><strong>松开</strong>该键 = 音符结束（NOTE_OFF）</li><li>多个键可以同时按下（和弦）</li></ul><hr><h2 id="第四步-观察控制台输出" tabindex="-1">第四步：观察控制台输出 <a class="header-anchor" href="#第四步-观察控制台输出" aria-label="Permalink to &quot;第四步：观察控制台输出&quot;">​</a></h2><p>演奏几个音符后，控制台会打印类似下面的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[tick] tick=8 bar=0 beat=2</span></span>
<span class="line"><span>[event] source=user tick=8 type=note_on pitch=60</span></span>
<span class="line"><span>[event] source=user tick=10 type=note_on pitch=62</span></span>
<span class="line"><span>[stats] hit_rate=None avg_backup_level=None round_trip_ms=145.2 server_process_ms=98.3 network_latency_ms=None total_hits=None total_ticks=None</span></span>
<span class="line"><span>[event] source=model tick=12 type=note_on pitch=45</span></span>
<span class="line"><span>[event] source=model tick=14 type=note_on pitch=48</span></span></code></pre></div><ul><li><code>source=user</code>：你演奏的音符</li><li><code>source=model</code>：AI 生成的伴奏音符</li><li><code>[stats]</code>：当次推理的往返延迟和服务端处理时间</li></ul><hr><h2 id="第五步-退出" tabindex="-1">第五步：退出 <a class="header-anchor" href="#第五步-退出" aria-label="Permalink to &quot;第五步：退出&quot;">​</a></h2><p>按 <code>Ctrl+C</code> 优雅地关闭系统。所有资源会被释放，若使用了日志输出模式，文件会在此时写入磁盘。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./configuration.html">配置项</a>：探索所有可用的 CLI 参数</li><li><a href="./../user-guide/output-types.html">输出类型</a>：尝试 <code>--output-type audio</code> 或 <code>--output-type composite</code></li><li><a href="./../user-guide/music-injection.html">音乐注入</a>：通过 HTTP API 注入历史（高级用法）</li></ul>`,30)])])}const k=a(n,[["render",d]]);export{u as __pageData,k as default};
